/* =====================================================================
 * world.js - highway, scenery, lighting
 * The road texture is generated by OUR OWN rasterizer (Bresenham lines +
 * DDA edge lines) and uploaded to the GPU as a texture.
 * World axes: +x right, +y up, player drives toward -z.
 * Authors : Sami (B25, R54139) & Zaid (B29, R54231)
 * ===================================================================== */
var World = (function () {
  var T = THREE;
  var LANES = 4, LANE_W = 3.6, ROAD_W = LANES * LANE_W, ROAD_HALF = ROAD_W / 2;
  var TILE = 28.8;                              // metres of road covered by one texture tile
  function laneX(i) { return -ROAD_HALF + LANE_W * (i + 0.5); }

  /* ---- road texture built pixel by pixel ---- */
  function makeRoadTexture() {
    var W = 256, H = 512, r = new CG.Raster(W, H);
    r.clear(52, 54, 60, 255);
    for (var i = 0; i < 9000; i++) {            // asphalt grain
      var g = 40 + (Math.random() * 40) | 0;
      r.putPixel(Math.random() * W, Math.random() * H, [g, g, g + 4, 255]);
    }
    var white = [235, 235, 235, 255], yel = [240, 190, 30, 255];
    for (var k = 0; k < 5; k++) {               // solid edge lines (Bresenham, 5px thick)
      r.lineBresenham(10 + k, 0, 10 + k, H - 1, white);
      r.lineBresenham(W - 15 + k, 0, W - 15 + k, H - 1, white);
    }
    var xs = [W / 4, W / 2, 3 * W / 4];         // dashed lane dividers (DDA)
    for (var d = 0; d < xs.length; d++) {
      var col = d === 1 ? white : white;
      for (var s = 0; s < 3; s++) {             // 3 dashes per tile, period = H/3
        var y0 = Math.round(s * H / 3), y1 = y0 + 54;
        for (var t = -1; t <= 1; t++) r.lineDDA(xs[d] + t, y0, xs[d] + t, y1, col);
      }
    }
    var c = document.createElement('canvas'); c.width = W; c.height = H;
    c.getContext('2d').putImageData(r.img, 0, 0);
    var tex = new T.CanvasTexture(c);
    tex.wrapS = tex.wrapT = T.RepeatWrapping; tex.anisotropy = 4;
    return tex;
  }

  function create(scene) {
    var w = { tiles: [], props: [] };
    /* lighting */
    w.scene = scene; w.hemi = new T.HemisphereLight(0xdcefff, 0x4a5d34, 0.95); scene.add(w.hemi);
    w.sun = new T.DirectionalLight(0xfff1d6, 0.85); w.sun.position.set(-30, 60, 20); scene.add(w.sun);
    scene.fog = new T.Fog(0xbad3ea, 70, 340);

    /* road (slightly transparent so the wet-road reflection of the player shows through) */
    w.roadTex = makeRoadTexture();
    w.roadTex.repeat.set(1, 600 / TILE);
    w.roadMat = new T.MeshLambertMaterial({ map: w.roadTex, transparent: true, opacity: 0.86 });
    var road = new T.Mesh(new T.PlaneGeometry(ROAD_W, 600, 1, 150), w.roadMat);
    road.rotation.x = -Math.PI / 2; road.position.set(0, 0, -240); scene.add(road);
    var base = new T.Mesh(new T.PlaneGeometry(160, 600, 1, 150), new T.MeshBasicMaterial({ color: 0x2b2e34 }));
    base.rotation.x = -Math.PI / 2; base.position.set(0, -4, -240); scene.add(base);

    /* grass on both sides, shoulders */
    var grassMat = new T.MeshLambertMaterial({ color: 0x4f8a3c }); w.grassMat = grassMat;
    [-1, 1].forEach(function (s) {
      var g = new T.Mesh(new T.PlaneGeometry(400, 600, 6, 150), grassMat);
      g.rotation.x = -Math.PI / 2; g.position.set(s * (ROAD_HALF + 200 - 0.05), -0.05, -240); scene.add(g);
      var rail = new T.Mesh(new T.BoxGeometry(0.15, 0.45, 600, 1, 1, 150), new T.MeshLambertMaterial({ color: 0xb9c0c7 }));
      rail.position.set(s * (ROAD_HALF + 0.35), 0.6, -240); scene.add(rail);
    });

    /* recycled scenery: each prop has a z, moved every frame, wrapped by 'span' */
    function addProp(mesh, x, z, span) { mesh.position.set(x, mesh.position.y, z); scene.add(mesh); w.props.push({ m: mesh, span: span }); }
    var trunk = new T.MeshLambertMaterial({ color: 0x6b4a2b });
    var leafA = new T.MeshLambertMaterial({ color: 0x2f7a35 }), leafB = new T.MeshLambertMaterial({ color: 0x3f9a45 });
    var gTrunk = new T.CylinderGeometry(0.25, 0.35, 2.2, 6), gCone = new T.ConeGeometry(1.7, 4.5, 8), gCone2 = new T.ConeGeometry(1.2, 3.2, 8);
    for (var i = 0; i < 26; i++) [-1, 1].forEach(function (s) {
      var tree = new T.Group(), t = new T.Mesh(gTrunk, trunk); t.position.y = 1.1; tree.add(t);
      var c1 = new T.Mesh(gCone, i % 2 ? leafA : leafB); c1.position.y = 4.2; tree.add(c1);
      var c2 = new T.Mesh(gCone2, leafB); c2.position.y = 6.3; tree.add(c2);
      var sc = 0.8 + Math.random() * 0.8; tree.scale.set(sc, sc, sc); tree.position.y = 0;
      addProp(tree, s * (ROAD_HALF + 4 + Math.random() * 40), 40 - i * 16 - Math.random() * 10, 416);
    });
    var postGeo = new T.BoxGeometry(0.18, 0.8, 0.18), postMat = new T.MeshLambertMaterial({ color: 0x888e95 });
    for (var j = 0; j < 40; j++) [-1, 1].forEach(function (s) {
      var p = new T.Mesh(postGeo, postMat); p.position.y = 0.4; addProp(p, s * (ROAD_HALF + 0.35), 40 - j * 10, 400);
    });
    var poleMat = new T.MeshLambertMaterial({ color: 0x70767d }), lampMat = new T.MeshBasicMaterial({ color: 0xfff6c8 });
    for (var k = 0; k < 8; k++) [-1, 1].forEach(function (s) {
      var pole = new T.Group();
      var st = new T.Mesh(new T.CylinderGeometry(0.1, 0.14, 8, 6), poleMat); st.position.y = 4; pole.add(st);
      var arm = new T.Mesh(geoB(2.2, 0.12, 0.12), poleMat); arm.position.set(-s * 1.0, 8, 0); pole.add(arm);
      var lamp = new T.Mesh(geoB(0.7, 0.1, 0.3), lampMat); lamp.position.set(-s * 2.0, 7.9, 0); pole.add(lamp);
      addProp(pole, s * (ROAD_HALF + 1.2), 20 - k * 50, 400);
    });
    function geoB(a, b, c) { return new T.BoxGeometry(a, b, c); }

    /* ---- extra scenery: bushes, rocks, houses, billboards ---- */
    var bushMat = new T.MeshLambertMaterial({ color: 0x3c7d36 }), bushGeo = new T.IcosahedronGeometry(0.9, 1);
    var rockMat = new T.MeshLambertMaterial({ color: 0x8a8d90 }), rockGeo = new T.IcosahedronGeometry(1, 0);
    for (var b = 0; b < 44; b++) {
      var bush = new T.Mesh(bushGeo, bushMat), bs = 0.7 + Math.random() * 1.1; bush.scale.set(bs * 1.3, bs * 0.8, bs); bush.position.y = 0.5 * bs;
      addProp(bush, (Math.random() < 0.5 ? -1 : 1) * (ROAD_HALF + 2 + Math.random() * 14), 40 - b * 9.5 - Math.random() * 5, 418);
    }
    for (var r = 0; r < 22; r++) {
      var rock = new T.Mesh(rockGeo, rockMat), rs = 0.5 + Math.random() * 1.3; rock.scale.set(rs * 1.4, rs, rs * 1.1); rock.rotation.y = Math.random() * 6; rock.position.y = rs * 0.5;
      addProp(rock, (Math.random() < 0.5 ? -1 : 1) * (ROAD_HALF + 3 + Math.random() * 25), 30 - r * 19 - Math.random() * 9, 418);
    }
    var wallCols = [0xe8d9c0, 0xd96a5a, 0xf2e6a0, 0xb9d3e8, 0xcfcfcf], roofGeo = new T.ConeGeometry(1, 1, 4);
    for (var h = 0; h < 14; h++) {
      var house = new T.Group(), hw = 5 + Math.random() * 4, hh = 3 + Math.random() * 2.5, hd = 5 + Math.random() * 4;
      var wall = new T.Mesh(geoB(hw, hh, hd), new T.MeshLambertMaterial({ color: wallCols[h % wallCols.length] })); wall.position.y = hh / 2; house.add(wall);
      var roof = new T.Mesh(roofGeo, new T.MeshLambertMaterial({ color: 0x8a3b2a })); roof.scale.set(hw * 0.78, 2.2, hd * 0.78); roof.rotation.y = Math.PI / 4; roof.position.y = hh + 1.1; house.add(roof);
      var door = new T.Mesh(geoB(1, 1.8, 0.1), new T.MeshLambertMaterial({ color: 0x5a3a24 })); door.position.set(0, 0.9, hd / 2 + 0.05); house.add(door);
      var side = h % 2 ? 1 : -1; house.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
      addProp(house, side * (ROAD_HALF + 22 + Math.random() * 28), 10 - h * 32 - Math.random() * 14, 450);
    }
    var ads = [['FUEL STOP', '#d1323c'], ['HOTEL  5 km', '#1f6fd1'], ['COFFEE', '#7a4a24'], ['SPEED LIMIT 120', '#222831'], ['WELCOME', '#2a9d4f'], ['RESTAURANT', '#f2a900']];
    for (var a = 0; a < 6; a++) {
      var cv = document.createElement('canvas'); cv.width = 256; cv.height = 128; var cx2 = cv.getContext('2d');
      cx2.fillStyle = ads[a][1]; cx2.fillRect(0, 0, 256, 128); cx2.strokeStyle = '#fff'; cx2.lineWidth = 6; cx2.strokeRect(5, 5, 246, 118);
      cx2.fillStyle = '#fff'; cx2.font = 'bold 34px Arial'; cx2.textAlign = 'center'; cx2.fillText(ads[a][0], 128, 78);
      var bb = new T.Group(), bpost = new T.MeshLambertMaterial({ color: 0x777c84 });
      [-3, 3].forEach(function (px) { var pst = new T.Mesh(geoB(0.25, 7, 0.25), bpost); pst.position.set(px, 3.5, 0); bb.add(pst); });
      var panel = new T.Mesh(geoB(8, 4, 0.2), new T.MeshBasicMaterial({ map: new T.CanvasTexture(cv) })); panel.position.y = 6.5; bb.add(panel);
      var sd = a % 2 ? 1 : -1; bb.rotation.y = sd > 0 ? -0.35 : 0.35;
      addProp(bb, sd * (ROAD_HALF + 9), -30 - a * 75, 450);
    }
    /* overhead highway sign gantries */
    var signTex = (function () {
      var c = document.createElement('canvas'); c.width = 256; c.height = 96; var x = c.getContext('2d');
      x.fillStyle = '#0b6b3a'; x.fillRect(0, 0, 256, 96); x.strokeStyle = '#fff'; x.lineWidth = 4; x.strokeRect(4, 4, 248, 88);
      x.fillStyle = '#fff'; x.font = 'bold 34px Arial'; x.textAlign = 'center'; x.fillText('HIGHWAY  7', 128, 42);
      x.font = 'bold 24px Arial'; x.fillText('CITY CENTRE  \u2192', 128, 76); return new T.CanvasTexture(c);
    })();
    for (var q = 0; q < 2; q++) {
      var gan = new T.Group(), steel = new T.MeshLambertMaterial({ color: 0x8c9299 });
      [-1, 1].forEach(function (s) { var l = new T.Mesh(geoB(0.4, 8, 0.4), steel); l.position.set(s * (ROAD_HALF + 0.9), 4, 0); gan.add(l); });
      var beam = new T.Mesh(geoB(ROAD_W + 2.2, 0.5, 0.5), steel); beam.position.y = 7.6; gan.add(beam);
      var sign = new T.Mesh(geoB(7, 2.6, 0.15), new T.MeshBasicMaterial({ map: signTex })); sign.position.set(0, 6.2, 0); gan.add(sign);
      addProp(gan, 0, -80 - q * 220, 440);
    }
    return w;
  }

  /* advance scenery by dz metres toward the camera (+z) and scroll the road */
  function update(w, dz) {
    w.roadTex.offset.y += dz / TILE;
    for (var i = 0; i < w.props.length; i++) {
      var p = w.props[i]; p.m.position.z += dz;
      if (p.m.position.z > 45) p.m.position.z -= p.span;
    }
  }
  return { LANES: LANES, LANE_W: LANE_W, ROAD_W: ROAD_W, ROAD_HALF: ROAD_HALF, laneX: laneX, create: create, update: update };
})();
